# What belongs to the rice:  repo-path:path-under-$HOME
# Generated files (matugen output: colors.kdl, colors.json, foot/themes/rice,
# gtk.css, hyprlock-rice.conf, btop/yazi/nvim/vesktop/zen themes) are NOT listed;
# they are rebuilt by quickshell/scripts/setwall.sh from matugen/templates.
FILES="
config/quickshell:.config/quickshell
config/niri/config.kdl:.config/niri/config.kdl
config/matugen/rice.toml:.config/matugen/rice.toml
config/matugen/templates/rice:.config/matugen/templates/rice
config/foot/foot.ini:.config/foot/foot.ini
config/fastfetch/config.jsonc:.config/fastfetch/config.jsonc
config/fastfetch/cross.txt:.config/fastfetch/cross.txt
config/swayidle/config:.config/swayidle/config
config/systemd/user/quickshell.service:.config/systemd/user/quickshell.service
local/bin/lock:.local/bin/lock
local/share/ascii-wall:.local/share/ascii-wall
local/share/rice/emoji.json:.local/share/rice/emoji.json
local/share/dbus-1/services:.local/share/dbus-1/services
p10k-rice.zsh:.p10k-rice.zsh
wallpapers/ascii-hands.png:Wallpapers/ascii-hands.png
system/rice-sys:.local/share/rice-sys
system/grub-arch-mono:.local/share/grub-arch-mono
system/plymouth-arch-mono:.local/share/plymouth-arch-mono
system/tuigreet-arch-mono:.local/share/tuigreet-arch-mono
"
